css:
.cd-stage, .im-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; }
.cd-stage canvas, .im-stage canvas { touch-action: none; cursor: grab; }
.cd-stage canvas.holding, .im-stage canvas.holding { cursor: grabbing; }
.cd-out, .im-out { margin: 0; font-size: 22px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 2.2em; }
.cd-out small, .im-out small { display: block; font-size: 18px; color: var(--ink-2); }
.cd-table { width: 100%; border-collapse: collapse; font-size: 20px; }
.cd-table th, .cd-table td { border: 1.5px solid var(--rule); padding: 4px 8px; text-align: center; }
.cd-table tbody th { text-align: left; }
.cd-table thead th { background: color-mix(in srgb, var(--accent) 12%, #fff); }
.cd-table td.ok { background: var(--good-soft); color: #1f6b3d; font-weight: 800; } .cd-table td.no { background: var(--risk-soft); color: #8f2a20; font-weight: 800; }
.im-table td { font-size: 18px; }

